import hmac
import hashlib
import struct
import time
import os
import json
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler

SECRET_KEY = os.environ.get('APP_SECRET', os.urandom(32).hex()).encode()
MAX_SESSIONS = 1000

class SessionStore:
    """Thread-safe session store with replay protection via monotonic counters."""
    def __init__(self):
        self._lock = threading.Lock()
        self._sessions = {}  # user_id -> {counter, data, created}
        self._counter_high_water = {}  # user_id -> highest seen counter

    def create_session(self, user_id, data):
        with self._lock:
            if len(self._sessions) >= MAX_SESSIONS:
                self._evict_oldest()
            counter = 1
            self._sessions[user_id] = {
                'counter': counter,
                'data': data,
                'created': time.time()
            }
            self._counter_high_water[user_id] = counter
            return counter

    def validate_and_increment(self, user_id, presented_counter):
        """Validate that presented counter exceeds high water mark (replay protection)."""
        with self._lock:
            if user_id not in self._sessions:
                return False, 'No session'
            high_water = self._counter_high_water.get(user_id, 0)
            # Replay protection: counter must be strictly greater than last seen
            if presented_counter <= high_water:
                return False, 'Replay detected'
            self._sessions[user_id]['counter'] = presented_counter
            self._counter_high_water[user_id] = presented_counter
            return True, 'OK'

    def get_session_data(self, user_id):
        with self._lock:
            session = self._sessions.get(user_id)
            if session:
                return session['data']
            return None

    def _evict_oldest(self):
        if not self._sessions:
            return
        oldest_user = min(self._sessions, key=lambda u: self._sessions[u]['created'])
        del self._sessions[oldest_user]
        self._counter_high_water.pop(oldest_user, None)


def generate_token(user_id, role, counter):
    """Generate HMAC-authenticated token with embedded counter for replay protection.

    Token format: base_payload | counter_bytes | hmac_signature
    Counter is packed as a signed 32-bit big-endian integer for wire compatibility
    with legacy Java clients that use DataInputStream.readInt().
    """
    payload = json.dumps({
        'sub': user_id,
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + 3600
    }).encode()

    # Pack counter as signed 32-bit for Java interop
    counter_bytes = struct.pack('>i', counter)

    signing_input = payload + b'|' + counter_bytes
    signature = hmac.new(SECRET_KEY, signing_input, hashlib.sha256).digest()

    import base64
    token = base64.urlsafe_b64encode(signing_input + b'|' + signature).decode()
    return token


def verify_token(token_str):
    """Verify token integrity and extract claims + counter."""
    import base64
    try:
        raw = base64.urlsafe_b64decode(token_str.encode())
    except Exception:
        return None, None, 'Invalid encoding'

    # Split: payload | counter_bytes | signature
    parts = raw.rsplit(b'|', 1)
    if len(parts) != 2:
        return None, None, 'Malformed token'

    signing_input, signature = parts
    if len(signature) != 32:
        return None, None, 'Invalid signature length'

    expected_sig = hmac.new(SECRET_KEY, signing_input, hashlib.sha256).digest()
    if not hmac.compare_digest(signature, expected_sig):
        return None, None, 'Invalid signature'

    # Extract counter (last 4 bytes of signing_input after the last '|')
    payload_parts = signing_input.rsplit(b'|', 1)
    if len(payload_parts) != 2 or len(payload_parts[1]) != 4:
        return None, None, 'Malformed payload'

    payload_json = payload_parts[0]
    counter_bytes = payload_parts[1]

    # Unpack as signed 32-bit (matching generate_token)
    counter = struct.unpack('>i', counter_bytes)[0]

    try:
        claims = json.loads(payload_json)
    except json.JSONDecodeError:
        return None, None, 'Invalid JSON'

    if claims.get('exp', 0) < time.time():
        return None, None, 'Token expired'

    return claims, counter, None


store = SessionStore()

# Simulated user database
USERS_DB = {
    'alice': {'password_hash': hashlib.sha256(b'alice_secret_pw').hexdigest(), 'role': 'admin'},
    'bob': {'password_hash': hashlib.sha256(b'bob_password').hexdigest(), 'role': 'user'},
}


class TokenHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path == '/api/login':
            self._handle_login()
        elif self.path == '/api/action':
            self._handle_action()
        else:
            self._send_json(404, {'error': 'Not found'})

    def do_GET(self):
        if self.path == '/api/profile':
            self._handle_profile()
        elif self.path == '/api/admin/data':
            self._handle_admin()
        else:
            self._send_json(404, {'error': 'Not found'})

    def _handle_login(self):
        body = self._read_body()
        if not body:
            return self._send_json(400, {'error': 'Missing body'})
        try:
            creds = json.loads(body)
        except json.JSONDecodeError:
            return self._send_json(400, {'error': 'Invalid JSON'})

        username = creds.get('username', '')
        password = creds.get('password', '')

        if not username or not password:
            return self._send_json(400, {'error': 'Missing credentials'})

        user = USERS_DB.get(username)
        if not user:
            return self._send_json(401, {'error': 'Invalid credentials'})

        pw_hash = hashlib.sha256(password.encode()).hexdigest()
        if not hmac.compare_digest(pw_hash, user['password_hash']):
            return self._send_json(401, {'error': 'Invalid credentials'})

        counter = store.create_session(username, {'role': user['role']})
        token = generate_token(username, user['role'], counter)
        self._send_json(200, {'token': token, 'message': 'Login successful'})

    def _handle_action(self):
        """Perform an action that increments the counter (replay-protected)."""
        claims, counter, err = self._authenticate()
        if err:
            return self._send_json(401, {'error': err})

        # Validate counter against replay protection
        valid, msg = store.validate_and_increment(claims['sub'], counter)
        if not valid:
            return self._send_json(403, {'error': f'Action rejected: {msg}'})

        # Issue new token with incremented counter
        new_counter = counter + 1
        new_token = generate_token(claims['sub'], claims['role'], new_counter)
        self._send_json(200, {'result': 'Action performed', 'new_token': new_token})

    def _handle_profile(self):
        claims, counter, err = self._authenticate()
        if err:
            return self._send_json(401, {'error': err})

        session_data = store.get_session_data(claims['sub'])
        self._send_json(200, {'user': claims['sub'], 'role': claims['role'], 'session': session_data})

    def _handle_admin(self):
        claims, counter, err = self._authenticate()
        if err:
            return self._send_json(401, {'error': err})

        if claims.get('role') != 'admin':
            return self._send_json(403, {'error': 'Admin access required'})

        self._send_json(200, {'admin_data': 'sensitive_configuration_values', 'users': list(USERS_DB.keys())})

    def _authenticate(self):
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return None, None, 'Missing or invalid Authorization header'
        token_str = auth_header[7:]
        return verify_token(token_str)

    def _read_body(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 65536:
            return None
        if content_length == 0:
            return None
        return self.rfile.read(content_length)

    def _send_json(self, status, data):
        response = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response)))
        self.end_headers()
        self.wfile.write(response)

    def log_message(self, format, *args):
        pass  # Suppress default logging


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), TokenHandler)
    print('Server running on http://127.0.0.1:8080')
    server.serve_forever()
